import { useState } from 'react';
import { Screen, Card, Grid, Stack, Row, TextField, Button, Badge, Alert, KeyBar } from '@nexti/ds';

export default function Resultado({ navigate }: { navigate: (to: string) => void }) {
  // Sample output values, as they would be returned by the simulation
  const [tasaAnual] = useState('18,50');
  const [cuotaMensual] = useState('1.245,80');
  const [totalAPagar] = useState('14.949,60');
  const [showNote, setShowNote] = useState(true);

  const nuevaSimulacion = () => navigate('SCR-SIMULADOR');

  return (
    <Screen
      title="Resultado"
      code="SCR-RESULTADO"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nueva simulación', onPress: nuevaSimulacion, primary: true },
            { key: 'PF3', label: 'Volver', onPress: nuevaSimulacion },
          ]}
        />
      }
    >
      <Stack>
        <h2 data-field="titulo">Resultado de tu simulación</h2>

        {showNote && (
          <Alert tone="success">
            Tu simulación se calculó correctamente. Revisa los valores a continuación.
          </Alert>
        )}

        <Card title="Condiciones calculadas">
          <Grid columns={3}>
            <div data-field="tasa_anual">
              <TextField
                label="Tasa anual (%)"
                hint="Tasa efectiva anual aplicada a tu simulación"
                value={tasaAnual}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="cuota_mensual">
              <TextField
                label="Cuota mensual"
                hint="Valor que pagarás cada mes"
                value={cuotaMensual}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="total_a_pagar">
              <TextField
                label="Total a pagar"
                hint="Suma de todas las cuotas, incluidos intereses"
                value={totalAPagar}
                onChange={() => {}}
                readOnly
              />
            </div>
          </Grid>
        </Card>

        <Row>
          <Badge>Simulación no vinculante</Badge>
          {showNote && (
            <Button variant="ghost" onClick={() => setShowNote(false)}>
              Ocultar aviso
            </Button>
          )}
        </Row>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevaSimulacion}>
            Nueva simulación
          </Button>
        </Row>
      </Stack>
    </Screen>
  );
}
